{
 "id": "gha/label-create-before-add",
 "severity": "advisory",
 "failureMessage": "--add-label fails when the label does not exist yet \u2014 GitHub will not create it on demand",
 "scanFiles": "/^\\.github\\/workflows\\/[^/]+\\.ya?ml$/",
 "scanTracked": true,
 "checkEachFile": [
  {
   "whenFileMatches": "/--add-label/",
   "require": "/label create/",
   "what": "uses --add-label with no idempotent `gh label create \u2026 || true` beforehand",
   "fix": "create the label idempotently before adding it, so the workflow survives its first run"
  }
 ]
}

